ALTER TABLE public.lotes_patio ADD COLUMN IF NOT EXISTS diametro_cm numeric, ADD COLUMN IF NOT EXISTS comprimento_m numeric;
ALTER TABLE public.pedidos ADD COLUMN IF NOT EXISTS itens jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN IF NOT EXISTS tipo_carga text NOT NULL DEFAULT 'madeira', ADD COLUMN IF NOT EXISTS volume_m3 numeric NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS qtd_blocos integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS qtd_pecas integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS unidade_venda text NOT NULL DEFAULT 'm3', ADD COLUMN IF NOT EXISTS quantidade_venda numeric NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS valor_unitario numeric NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS situacao_pagamento text NOT NULL DEFAULT 'pendente', ADD COLUMN IF NOT EXISTS data_entrega date;
ALTER TABLE public.pedidos ADD CONSTRAINT pedidos_tipo_carga_check CHECK (tipo_carga IN ('madeira','cilindrica','cavaco','po_serra')), ADD CONSTRAINT pedidos_unidade_venda_check CHECK (unidade_venda IN ('m3','ton')), ADD CONSTRAINT pedidos_situacao_pagamento_check CHECK (situacao_pagamento IN ('pendente','pago','permuta'));